11/20/boq_item_sample_file_2026-11-20-13-23-03_ca103dd6165c345516c24ba6f6e2e534.csv","csv_hash":"cacf146879a17bd722608fb7ede9dac7d4caaec341ee8c815c54bc04a21f5512"},{"bid":"GEM/2026/B/8304231","rows":[{"n":"1","name":"Pure Tone Audiometer (Diagnostic) (V3)","quantity":1,"unit":"pieces","page":1,"specification":"A.1. Channel: Two separate with independent attenuators.\nA.2. Stimulus type: Tone, warble, pulsed tone, pulsed warble, (Frequency specific Hearing assessment noise)\nA.3. Special tests: SISI, ABLB, Tone Decay, Free field (Complete setup, including speakers), Speech test, Word Recognition.\nA.4. Frequency range:\nA4.1. TDH 39 earphone- 250 to 8000 Hz or more\nA4.2. Insert ear phones- 250 to 8000 Hz or more\nA4.3. Bone conduction (BC)- 250 to 4000Hz\nA.5. Level Range:\nA5.1. Air conduction (AC): -10dBHL to 120dBHL\nA5.2. Bone Conduction: -10dBHL to +80 dBHL\nA5.3. Speech: -10dBHL to 100dBHL\nA5.4. Masking: -10dBHL to 100dBHL\nA.6. Masking types: Narrow band noise, Speech Noise, White noise.\nA.7. Stimulus modulation:\nA7.1. Warble Tone: 1to 10Hz + 5% Modulation\nA7.2. SISI: 5, 2, 1 dB decrements.\nA.8. Should have full speed USB port connector (3.0 or more).\nA.9. Should be supplied with required software with updates in CD/DVD.\nA.10. Data storage facilities unlimited with computer software\nA.11. External Input: CD player, Tap recorder or Microphone\nA.12. Equipment should be provided with required electricity safety equipment (UPS) and compatible with 220 V-50 Hz, AC Supply.\nA.13. The setup should have two-way talk-back facility.\nA.14. The system should be provided with a compatible laser colour printer.\nA.15. Equipment should conform to US FDA/European CE standards.\nPC/Laptops systems, wherever mentioned should include genuine/licensed operating system, licensed MS Office Home & Business (Latest Version), licensed Adobe Acrobat Full Version, licensed standard anti-virus software with all backup (DVD etc.) media of all the software and all the accessories to run the required software seamlessly.","question":"The main bid p. 4 permits 1 or 2 channels. Is the two-channel requirement in A.1 mandatory?"}],"common":null,"source":"https://fulfilment.gem.gov.in/contract/slafds?fileDownloadPath=SLA_UPLOAD_PATH/2026/Nov/GEM_2026_B_8304231/CLM0010/audmeter_b8e9c921-9023-40d5-889b1795261799021_gmcspr03.pdf","sha":"a06e234088ffdc1a99cab61ac3c383e5c3632172699540038bddf0ba302b7480","csv_url":"https://bidplus.gem.gov.in/showbidDocument/10200810","csv_hash":"9153f056e27c5894abd6b46aaded5b4f05bf7f6428949b112fac3eaf25b9b15d","allow":[["https://bidplus.gem.gov.in/showbidDocument/10200810","9153f056e27c5894abd6b46aaded5b4f05bf7f6428949b112fac3eaf25b9b15d"],["https://fulfilment.gem.gov.in/contract/slafds?fileDownloadPath=SLA_UPLOAD_PATH/2026/Nov/GEM_2026_B_8304231/CLM0010/audmeter_b8e9c921-9023-40d5-889b1795261799021_gmcspr03.pdf","a06e234088ffdc1a99cab61ac3c383e5c3632172699540038bddf0ba302b7480"]]}]$review$::jsonb) x),
checked as (
 select t.id,x,public.bid_pack_extracted_source(t.id,false) raw
 from batches join public.tenders t on t.bid_number=x->>'bid'
 where t.status='published' and t.reviewed_at is not null and exists(select from public.tender_documents
 where tender_id=t.id and official_url=x->>'source' and content_hash=x->>'sha' and availability='available')
 and not exists(select from public.tender_documents d where d.tender_id=t.id and d.availability is distinct from 'removed'
 and not exists(select from jsonb_array_elements(x->'allow') a where a->>0=d.official_url and a->>1=d.content_hash))
), matched as (
 select id,x,raw,mapped.rows from checked
 cross join lateral (select jsonb_agg(jsonb_strip_nulls(v||jsonb_build_object('name',i->>'name','condition',x->>'common')) order by (v->>'n')::int) rows
 from jsonb_array_elements(x->'rows') v join jsonb_array_elements(raw->'items') i on
 i->>'item_number'=v->>'n' and i->'quantity'=v->'quantity' and i->>'unit'=v->>'unit'
 and lower(regexp_replace(trim(i->>'name'),'[[:space:]]+',' ','g'))=lower(regexp_replace(trim(v->>'name'),'[[:space:]]+',' ','g'))
 and i->>'source_url'=x->>'csv_url' and i->>'source_hash'=x->>'csv_hash') mapped
 where jsonb_array_length(raw->'items')=jsonb_array_length(x->'rows') and jsonb_array_length(mapped.rows)=jsonb_array_length(x->'rows')
)
insert into public.tender_specification_reviews(tender_id,base_version,source_url,source_sha,reviewed_at,rows)
select id,raw->>'version',x->>'source',x->>'sha',now(),rows from matched
where (raw->'expected'->>'count')::int=jsonb_array_length(rows)
on conflict do nothing;
